import logo from './logo.svg';
import './App.css';
import React, {useEffect, useState} from 'react'

function App() {
  const [backendData, setBackendData] = useState([{}])


  return (
    <div className="App">
      <div>client</div>
      {(typeof backendData.users == 'undefined') ? (
      <p>Loading...</p>
      ) : (
      backendData.users.map((user, i) => (
        <p key={i}>{user}</p>
      ))
      )}
    </div>
  );
}

export default App;
